namespace {

const schema::RpcSchema& rpc_of(const char* name) {
    const schema::RpcSchema* r = schema_named("AoCPlayerControllerBP_C").rpc(name);
    if (!r) {
        std::printf("  [FAIL] no RPC %s\n", name);
        std::exit(2);
    }
    return *r;
}

std::optional<RpcCall> read_call(const schema::RpcSchema& rpc, const Bits& bits) {
    return with_exact(bits, [&](const uint8_t* d, size_t, size_t n) -> std::optional<RpcCall> {
        size_t pos = 0;
        auto p = read_rpc_params(rpc, d, n, pos, {});
        if (!p || pos != n) return std::nullopt;
        RpcCall c;
        c.rpc = &rpc;
        c.params = std::move(*p);
        c.decoded = true;
        c.param_bits = n;
        return c;
    });
}

Bits written(const schema::RpcSchema& rpc, const RpcParams& params) {
    BunchWriter w;
    bool failed = false;
    write_rpc_params(rpc, params, w, {}, &failed);
    if (failed) return Bits();
    return Bits(w);
}
// built by CoA with C-Y-B

void test_events() {
    std::printf("the 24 retail events that fill the Resource containers\n");
    const schema::RpcSchema& rpc = rpc_of("ClientReceiveStorageEvent");
    const size_t n = sizeof(cr::kHarvests) / sizeof(cr::kHarvests[0]);
    CHECK(n == 24, "24 events (the research counted 25: its table has 24 rows)");
    size_t read = 0, typed = 0, rewritten = 0, rebuilt = 0, res0 = 0, res1 = 0, shape = 0, full_ok = 0, ranges = 0;
    std::set<std::array<uint32_t, 4>> guids;
    for (const cr::Harvest& h : cr::kHarvests) {
        const Bits bits = bits_of_hex(h.hex, h.bits);
        const auto call = read_call(rpc, bits);
        if (!call) continue;
        ++read;
        const auto e = parse_storage_event(*call);
        if (!e) continue;
        const bool one = e->type == static_cast<uint8_t>(StorageEventType::Add) && e->targets.size() == 1 && e->targets[0].slots.size() == 1 && e->targets[0].status == kStorageNoError &&
                         e->move_source.object.ObjectId == 0 && e->move_source.slots.empty() && e->item.has_item;
        if (!one) continue;
        const StorageEventContainer& t = e->targets[0];
        const StorageEventSlot& s = t.slots[0];
        const bool fields = t.object.ObjectId == h.object && s.slot == h.slot && s.count == h.count && static_cast<uint32_t>(s.count) == h.quantity && e->item.record_id == h.record &&
                            e->item.quantity == h.quantity && e->item.quality == h.quality && s.item_guid.a == h.guid[0] && s.item_guid.b == h.guid[1] && s.item_guid.c == h.guid[2] &&
                            s.item_guid.d == h.guid[3] && e->item.guid == s.item_guid;
        if (fields) ++typed;
        if (const auto params = storage_event_params(rpc, *e); params && written(rpc, *params) == bits) ++rewritten;
        // the same event from what it says
        ItemStorageEvent mine;
        mine.type = static_cast<uint8_t>(StorageEventType::Add);
        mine.item = e->item;
        mine.instigator = e->instigator;
        StorageEventContainer target;
        target.object = e->targets[0].object;
        target.slots.push_back({h.slot, h.count, e->item.guid});
        mine.targets.push_back(target);
        if (const auto params = storage_event_params(rpc, mine); params && written(rpc, *params) == bits) ++rebuilt;
        (h.offset == 8 ? res0 : res1) += (h.offset == 8 || h.offset == 10) ? 1 : 0;
        shape += (h.offset == 8 || h.offset == 10) && h.slot >= 0 && h.slot < 40 ? 1 : 0;
        full_ok += h.full_bits == h.bits + h.toast_bits && h.toast_bits > 5000 && h.toast_bits < 7000 ? 1 : 0;
        ranges += h.quantity >= 1 && h.quantity <= 99 && h.quality >= 1 && h.quality <= 200 && h.record != 0 ? 1 : 0;
        guids.insert({h.guid[0], h.guid[1], h.guid[2], h.guid[3]});
    }
    CHECK(read == n, "all 24 read to their last bit");
    CHECK(typed == n, "each is an Add with one target container, one slot whose count is the item's quantity and whose guid is the item's, status 14, no move source");
    CHECK(rewritten == n, "typed and written back, the exact bits of the capture");
    CHECK(rebuilt == n, "built from the target, slot, count and item alone: the exact bits too");
    CHECK(res0 == 18 && res1 == 6, "18 events fill Resource0 and 6 Resource1 (the Equipment container's id + 8 and + 10)");
    CHECK(shape == n, "every slot is below 40 (the cells of the largest bag these characters wore)");
    CHECK(full_ok == n, "the event as captured is longer by the callout only: 5 to 7 kbit");
    CHECK(ranges == n && guids.size() == n, "each item has a record, a quantity of 1 to 99 and a quality of 1 to 200; the 24 instance guids differ");
}

bool ends_with(const std::string& s, const std::string& tail) { return s.size() >= tail.size() && s.compare(s.size() - tail.size(), tail.size(), tail) == 0; }

void test_full_events() {
    std::printf("the 24 events as captured, with the pick-up popup's callout\n");
    const schema::RpcSchema& rpc = rpc_of("ClientReceiveStorageEvent");
    const size_t n = sizeof(cr::kHarvests) / sizeof(cr::kHarvests[0]);
    size_t read = 0, set = 0, text_ok = 0, copy_ok = 0, item_ok = 0, constants = 0, empty_rest = 0, rewritten = 0, stripped_ok = 0, qty_form = 0, bands = 0, no_extras = 0;
    for (const cr::Harvest& h : cr::kHarvests) {
        const Bits bits = bits_of_hex(h.full_hex, h.full_bits);
        const auto call = read_call(rpc, bits);
        if (!call) continue;
        const auto e = parse_storage_event(*call);
        if (!e) continue;
        ++read;
        if (!e->callout) continue;
        ++set;
        const CalloutQueueInfo& c = *e->callout;
        const std::string head = "Acquired <a id=\"Item\" style=\"Item_";
        const std::string guid = "\" metaType=\"ItemLink\" metaGUID=\"" + std::to_string(h.record) + "\" metaItemQuality=\"" + std::to_string(h.quality) + "\" metaEnchantLevel=\"0\" metaTemperingPercent=\"0\" metaDurability=\"0\" metaSockets=\"\"> [";
        const size_t band_end = c.message.find(guid);
        text_ok += c.message.compare(0, head.size(), head) == 0 && band_end != std::string::npos ? 1 : 0;
        if (band_end != std::string::npos) {   // the band is the one of the quality: Common 1-5, Uncommon 6-15, Rare 16-30, Heroic 31-50
            const std::string band = c.message.substr(head.size(), band_end - head.size());
            bands += band == (h.quality <= 5 ? "Common" : h.quality <= 15 ? "Uncommon" : h.quality <= 30 ? "Rare" : "Heroic") ? 1 : 0;
        }
        qty_form += (h.quantity > 1 ? ends_with(c.message, "] </>x" + std::to_string(h.quantity)) : ends_with(c.message, "]</>") && c.message.find("</>x") == std::string::npos) ? 1 : 0;
        copy_ok += c.formatted_on_screen == c.message ? 1 : 0;
        item_ok += c.item == e->item ? 1 : 0;
        constants += c.callout_type == 6 && c.point_size == 36 && c.chat_category == 141 ? 1 : 0;
        empty_rest += c.text_message == TextValue{} && c.localized_message == LocalizedMessage{} && c.from_source_player.empty() && c.chat_emblems.empty() && c.node_level == 0 && !c.sent_by_gm &&
                              c.toast_record_id == 0 && c.action_response_id == 0 && c.context_location == Vec3d{} && c.creation_time.ticks > 600000000000000000ll
                          ? 1
                          : 0;
        no_extras += !e->extra_guid_a && !e->extra_i64 && !e->extra_guid_b && e->targets.size() == 1 ? 1 : 0;
        if (const auto params = storage_event_params(rpc, *e); params && written(rpc, *params) == bits) ++rewritten;
        ItemStorageEvent bare = *e;
        bare.callout.reset();
        if (const auto params = storage_event_params(rpc, bare); params && written(rpc, *params) == bits_of_hex(h.hex, h.bits)) ++stripped_ok;
    }
    CHECK(read == n && set == n, "all 24 read to their last bit with the optional callout set");
    CHECK(text_ok == n && bands == n, "the message is Acquired <a id=Item style=Item_<band> metaType=ItemLink metaGUID=<record> metaItemQuality=<quality> ...> [<name>]..., the band the quality's (Common, Uncommon, Rare, Heroic)");
    CHECK(qty_form == n, "ending [name] </>x<quantity> for a quantity above 1 and [name]</> (no x1, no space) for 1");
    CHECK(copy_ok == n && item_ok == n, "FormattedOnScreenMessage is the message again and ItemAssociated is the event's own item (guid, quantity and all)");
    CHECK(constants == n, "SetCalloutType 6, PointSize 36 and ChatCategory 141 in every one");
    CHECK(empty_rest == n && no_extras == n, "nothing else is set: no FText, no localized message, no names or emblems, ids and location 0, the time of day (ticks) only");
    CHECK(rewritten == n, "typed and written back, the exact bits of the capture");
    CHECK(stripped_ok == n, "without the callout the same event is the toastless one: the exact bits of `hex`");
}

void test_refusals() {
    std::printf("what is not a resource event\n");
    const schema::RpcSchema& rpc = rpc_of("ClientReceiveStorageEvent");
    const cr::Harvest& h = cr::kHarvests[0];
    const auto call = read_call(rpc, bits_of_hex(h.hex, h.bits));
    const auto e = call ? parse_storage_event(*call) : std::nullopt;
    CHECK(e.has_value(), "the first event reads");
    if (!e) return;
    ItemStorageEvent none = *e;
    none.targets.clear();
    CHECK(storage_event_params(rpc, none).has_value(), "an event with no target is writable (the codec does not judge)");
    CHECK(!storage_event_params(rpc_of("ClientRemoveListenerFromStorage"), *e), "another RPC is refused");
}

}  // namespace

int main() {
    std::printf("test_repl_resource\n");
    test_events();
    test_full_events();
    test_refusals();
    std::printf("\n%d passed, %d failed\n", g_pass, g_fail);
    return g_fail ? 1 : 0;
}
